import createClient from 'openapi-fetch';
import { ApiError } from './errors';
import type { paths } from './schema.gen';

/**
 * The typed API client. Paths, params and bodies are checked against the server's OpenAPI
 * document (schema.gen.ts, regenerated by `make gen-api`). Same origin in every environment:
 * Vite proxies `/api` in development and the server serves the app in production.
 */
export const api = createClient<paths>({
  baseUrl: import.meta.env['VITE_API_BASE_URL'] ?? globalThis.location?.origin ?? '',
  // Look `fetch` up per call rather than capturing it at import time, so test mocks (MSW) and
  // polyfills installed later are honoured.
  fetch: (request) => globalThis.fetch(request),
});

type FetchResult<D> =
  { data: D; error?: never; response: Response } | { data?: never; error: unknown; response: Response };

/**
 * Awaits an `api.GET/POST/...` call and returns its data, or throws {@link ApiError}. Query and
 * mutation functions use this so TanStack Query sees failures as rejections.
 *
 *   const page = await unwrap(api.GET('/api/v1/notes', { params: { query: { limit: 20 } } }));
 */
export async function unwrap<D>(call: Promise<FetchResult<D>>): Promise<D> {
  let result: FetchResult<D>;
  try {
    result = await call;
  } catch (cause) {
    throw ApiError.network(cause);
  }
  if (result.error !== undefined || !result.response.ok) {
    throw ApiError.fromResponse(result.response, result.error);
  }
  return result.data as D;
}
